<template><section class="admin-panel"><header class="admin-section-head"><div><p>CONTENT MODERATION</p><h1>动态管理</h1></div><button type="button" @click="$emit('retry')">刷新</button></header><AdminState :loading="loading" :error="error" @retry="$emit('retry')"/><div v-if="!loading&&!error" class="admin-list"><article v-for="post in posts" :key="post.id"><div><strong>{{ post.author }} · {{ post.sceneName }}</strong><span>{{ post.content }}</span></div><button class="danger" type="button" @click="requestDelete(post)">强制删除</button></article></div><ConfirmDialog v-if="target" title="删除动态" :message="`删除 ${target.author} 的动态后无法恢复。`" @cancel="target=null" @confirm="confirm"/></section></template>
<script setup lang="ts">import{ref}from"vue";import type{AdminPost}from"../../services/admin";import AdminState from"./AdminState.vue";import ConfirmDialog from"./ConfirmDialog.vue";defineProps<{posts:AdminPost[];loading:boolean;error?:string}>();const emit=defineEmits<{retry:[];remove:[post:AdminPost,reason:string]}>();const target=ref<AdminPost|null>(null);function requestDelete(post:AdminPost){target.value=post}function confirm(){if(target.value)emit("remove",target.value,"管理员强制删除");target.value=null}</script>
